#!/usr/bin/perl
use strict;
use warnings;
use v5.10;

# Check whether a string is a palindrome.
# Strip whitespace and punctuation, then compare the string with its reverse.
# Case is preserved, so "Abba" returns true and "Abba" reversed is "abba".
# Change this if a different kind of match is wanted.
sub is_palindrome {
    my ($string) = @_;
    die "input is a string" unless defined $string;
    my $clean = $string;
    $clean =~ s/\s+//g;      # every run of whitespace, anywhere, gone
    $clean =~ s/[^A-Za-z0-9]//g;
    return $clean eq reverse $clean;
}

# One line per string. Plain words, and the right answer every time.
